/// VER-1 for `process.ProcessHost`: an ordinal no message has is
/// refused by the validator, which `decode_exact` runs first,
/// whatever follows it (bounds: 2 to 4 bytes). The message
/// validators are stubbed: none may run.
#[cfg(kani)]
#[kani::proof]
#[kani::unwind(6)]
#[kani::stub(ProcessHost::validate_ready, kani_any_process_host_validation)]
#[kani::stub(ProcessHost::validate_pong, kani_any_process_host_validation)]
fn verify_process_host_unknown_ordinal() {
    let ordinal: u16 = kani::any_where(|&n: &u16| usize::from(n) >= 2);
    let tail: [u8; 2] = kani::any();
    let len: usize = kani::any_where(|&n: &usize| (2..=4).contains(&n));
    let [o0, o1] = ordinal.to_le_bytes();
    let [t0, t1] = tail;
    let bytes = [o0, o1, t0, t1];
    let Some(input) = bytes.get(..len) else {
        return;
    };
    assert!(ProcessHost::validate_bytes(input) == Err(BadMessage::UnknownOrdinal));
}

/// Browser to child, on the bootstrap endpoint.
///
/// Interface `process.ProcessControl`: bound, capacity 64, overflow `terminate`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ProcessControl {
    /// Asks the child to answer with `ProcessHost.pong`.
    Ping {
        /// Echoed in the answer.
        nonce: u64,
    },
    /// Tells the child to exit.
    Exit {
        /// Why.
        reason: ExitReason,
    },
    /// What the child is for; sent once, after `ready` is accepted.
    Start {
        /// The child's configuration.
        config: ChildConfig,
    },
}

impl ProcessControl {
    /// What the `.hgidl` declared about this interface.
    pub const INFO: hg_ipc::InterfaceInfo = hg_ipc::InterfaceInfo {
        name: "process.ProcessControl",
        binding: hg_ipc::Binding::Bound,
        capacity: 64,
        overflow: hg_ipc::Overflow::Terminate,
        max_message_len: hg_ipc::wire::len_add(
            2,
            hg_ipc::wire::len_max(
                hg_ipc::wire::len_max(
                    hg_ipc::wire::len_add(0, <u64 as Wire>::MAX_LEN),
                    hg_ipc::wire::len_add(0, <ExitReason as Wire>::MAX_LEN),
                ),
                hg_ipc::wire::len_add(0, <ChildConfig as Wire>::MAX_LEN),
            ),
        ),
    };
}

impl ProcessControl {
    /// Reads [`Self::Ping`]'s fields, after its ordinal.
    fn decode_ping(r: &mut Reader<'_>) -> Result<(u64,), BadMessage> {
        Ok((Wire::decode(r)?,))
    }
    /// Checks [`Self::Ping`]'s fields, after its ordinal.
    fn validate_ping(r: &mut Reader<'_>) -> Result<(), BadMessage> {
        <u64 as Wire>::validate(r)?;
        Ok(())
    }
    /// Writes [`Self::Ping`]'s fields, after its ordinal.
    fn encode_ping(w: &mut Writer, nonce: &u64) {
        nonce.encode(w);
    }
    /// Reads [`Self::Exit`]'s fields, after its ordinal.
    fn decode_exit(r: &mut Reader<'_>) -> Result<(ExitReason,), BadMessage> {
        Ok((Wire::decode(r)?,))
    }
    /// Checks [`Self::Exit`]'s fields, after its ordinal.
    fn validate_exit(r: &mut Reader<'_>) -> Result<(), BadMessage> {
        <ExitReason as Wire>::validate(r)?;
        Ok(())
    }
    /// Writes [`Self::Exit`]'s fields, after its ordinal.
    fn encode_exit(w: &mut Writer, reason: &ExitReason) {
        reason.encode(w);
    }
    /// Reads [`Self::Start`]'s fields, after its ordinal.
    fn decode_start(r: &mut Reader<'_>) -> Result<(ChildConfig,), BadMessage> {
        Ok((Wire::decode(r)?,))
    }
    /// Checks [`Self::Start`]'s fields, after its ordinal.
    fn validate_start(r: &mut Reader<'_>) -> Result<(), BadMessage> {
        <ChildConfig as Wire>::validate(r)?;
        Ok(())
    }
    /// Writes [`Self::Start`]'s fields, after its ordinal.
    fn encode_start(w: &mut Writer, config: &ChildConfig) {
        config.encode(w);
    }
}

impl Wire for ProcessControl {
    fn encode(&self, w: &mut Writer) {
        match self {
            Self::Ping { nonce } => {
                0u16.encode(w);
                Self::encode_ping(w, nonce);
            }
            Self::Exit { reason } => {
                1u16.encode(w);
                Self::encode_exit(w, reason);
            }
            Self::Start { config } => {
                2u16.encode(w);
                Self::encode_start(w, config);
            }
        }
    }
    fn decode(r: &mut Reader<'_>) -> Result<Self, BadMessage> {
        match u16::decode(r)? {
            0 => {
                let (nonce,) = Self::decode_ping(r)?;
                Ok(Self::Ping { nonce })
            }
            1 => {
                let (reason,) = Self::decode_exit(r)?;
                Ok(Self::Exit { reason })
            }
            2 => {
                let (config,) = Self::decode_start(r)?;
                Ok(Self::Start { config })
            }
            _ => Err(BadMessage::UnknownOrdinal),
        }
    }
    fn validate(r: &mut Reader<'_>) -> Result<(), BadMessage> {
        match u16::decode(r)? {
            0 => Self::validate_ping(r),
            1 => Self::validate_exit(r),
            2 => Self::validate_start(r),
            _ => Err(BadMessage::UnknownOrdinal),
        }
    }
    const MIN_LEN: usize = hg_ipc::wire::len_add(
        2,
        hg_ipc::wire::len_min(
            hg_ipc::wire::len_min(
                hg_ipc::wire::len_add(0, <u64 as Wire>::MIN_LEN),
                hg_ipc::wire::len_add(0, <ExitReason as Wire>::MIN_LEN),
            ),
            hg_ipc::wire::len_add(0, <ChildConfig as Wire>::MIN_LEN),
        ),
    );
    const MAX_LEN: usize = hg_ipc::wire::len_add(
        2,
        hg_ipc::wire::len_max(
            hg_ipc::wire::len_max(
                hg_ipc::wire::len_add(0, <u64 as Wire>::MAX_LEN),
                hg_ipc::wire::len_add(0, <ExitReason as Wire>::MAX_LEN),
            ),
            hg_ipc::wire::len_add(0, <ChildConfig as Wire>::MAX_LEN),
        ),
    );
}

impl ProcessControl {
    /// Checks that `bytes` are one valid message, allocating nothing.
    ///
    /// # Errors
    /// [`BadMessage`] if they are not.
    pub fn validate_bytes(bytes: &[u8]) -> Result<(), BadMessage> {
        let mut r = Reader::new(bytes);
        match u16::decode(&mut r)? {
            0 => Self::validate_ping(&mut r)?,
            1 => Self::validate_exit(&mut r)?,
            2 => Self::validate_start(&mut r)?,
            _ => return Err(BadMessage::UnknownOrdinal),
        }
        r.finish()
    }
}

impl hg_ipc::Interface for ProcessControl {
    const INFO: hg_ipc::InterfaceInfo = Self::INFO;
    fn into_wire(self) -> (Vec<u8>, Vec<hg_ipc::Handle>) {
        let mut w = Writer::new();
        match self {
            Self::Ping { nonce } => {
                0u16.encode(&mut w);
                Self::encode_ping(&mut w, &nonce);
            }
            Self::Exit { reason } => {
                1u16.encode(&mut w);
                Self::encode_exit(&mut w, &reason);
            }
            Self::Start { config } => {
                2u16.encode(&mut w);
                Self::encode_start(&mut w, &config);
            }
        }
        (w.into_bytes(), Vec::new())
    }
    fn from_wire(
        bytes: &[u8],
        handles: Vec<hg_ipc::Handle>,
        ipc: &std::sync::Arc<dyn hg_ipc::Ipc>,
    ) -> Result<Self, BadMessage> {
        let _ = ipc;
        // Every check before any decoding: the bytes by the validator,
        // which allocates nothing, then the handles' kinds (IPC-R1).
        Self::validate_bytes(bytes)?;
        let mut r = Reader::new(bytes);
        let msg = match u16::decode(&mut r)? {
            0 => {
                hg_ipc::endpoint::expect_kinds(handles.iter().map(hg_ipc::Handle::kind), &[])?;
                let (nonce,) = Self::decode_ping(&mut r)?;
                Self::Ping { nonce }
            }
            1 => {
                hg_ipc::endpoint::expect_kinds(handles.iter().map(hg_ipc::Handle::kind), &[])?;
                let (reason,) = Self::decode_exit(&mut r)?;
                Self::Exit { reason }
            }
            2 => {
                hg_ipc::endpoint::expect_kinds(handles.iter().map(hg_ipc::Handle::kind), &[])?;
                let (config,) = Self::decode_start(&mut r)?;
                Self::Start { config }
            }
            _ => return Err(BadMessage::UnknownOrdinal),
        };
        r.finish()?;
        Ok(msg)
    }
}

